import{_ as s,J as t,b as o,e as r,a8 as i,f as p,L as n}from"./chunks/framework.CNHV3T2x.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TCustomResampler","kind":"Class","declaration":"TCustomResampler = class(TCustomSampler)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TCustomSampler","TCustomResampler"],"summary":"Abstract base class for pixel resampling and filtering algorithms attached to `TBitmap32`.","date":1787856744000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TCustomResampler/index.md","filePath":"api/GR32/Classes/TCustomResampler/index.md","lastUpdated":1787856744000,"timestamp":1787856744000,"datetime":"2026-08-27T18:52:24.000Z","contributors":[]}'),c={name:"api/GR32/TCustomResampler/index.md"};function m(l,e,d,u,T,h){const a=t("ApiMembers");return o(),r("div",null,[e[0]||(e[0]=i('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCustomResampler</code> is the abstract base class for all bitmap resamplers in Graphics32. It inherits from <code>TCustomSampler</code> and adapts generic sub-pixel color sampling specifically for <code>TCustomBitmap32</code> instances.</p><p>Resamplers provide spatial filtering and interpolation algorithms (such as Nearest Neighbor, Linear, Cubic, or Kernel resamplers) used when stretching, transforming, or sampling bitmaps.</p><p>The <code>Bitmap</code> property associates the resampler with its source bitmap. The <code>PixelAccessMode</code> property controls out-of-bounds pixel sampling behavior (<code>pamUnsafe</code>, <code>pamSafe</code>, <code>pamWrap</code>, or <code>pamTransparentEdge</code>).</p>',4)),p("p",null,[n(a,{type:"members"})])])}const b=s(c,[["render",m]]);export{_ as __pageData,b as default};
